<template>
 <view class="local-cutout">
  <text class="cutout-note">本地试用 · 按背景颜色去除，不会自动识别人物或建筑。背景复杂时请圈选主体，再用擦除 / 补回修边。</text>
  <view class="cutout-tools"><button :disabled="busy||generating||!loaded" @click="autoMask">自动去背景</button><button :disabled="busy||generating||!loaded" :aria-pressed="tool==='polygon'" :class="{active:tool==='polygon'}" @click="startPolygon">圈出主体</button><button :disabled="busy||generating||!loaded" :aria-pressed="tool==='background'" :class="{active:tool==='background'}" @click="tool='background'">点选背景</button><button :disabled="busy||generating||!loaded" :aria-pressed="tool==='erase'" :class="{active:tool==='erase'}" @click="tool='erase'">擦除</button><button :disabled="busy||generating||!loaded" :aria-pressed="tool==='restore'" :class="{active:tool==='restore'}" @click="tool='restore'">补回</button><button :disabled="busy||generating||!history.length" @click="undo">撤销</button></view>
  <view class="cutout-canvas-heading"><text>1 · 编辑主体</text><button :disabled="generating||!loaded" @click="showOriginal=!showOriginal;paint()">{{ showOriginal ? '查看抠图' : '对照原图' }}</button></view>
  <view :id="canvasId" class="cutout-editor"/>
  <text class="cutout-instruction">{{ tool==='polygon' ? '沿主体轮廓逐点点击，至少 3 点后完成圈选。' : tool==='background' ? '点击要去除的背景；只删除颜色相近、连通的部分。' : '在图片上拖动'+(tool==='erase'?'擦掉背景':'补回误删主体')+'，松手生效。' }}</text>
  <view v-if="tool==='polygon'" class="polygon-actions"><text>已选 {{ polygon.length }} / 128 点</text><view class="cutout-tools"><button :disabled="generating||polygon.length<3" @click="finishPolygon">完成圈选</button><button :disabled="generating||!polygon.length" @click="polygon.pop();paint()">撤回一点</button><button :disabled="generating" @click="polygon=[];tool='background';paint()">取消圈选</button></view></view>
  <view class="cutout-tools"><button :disabled="busy||generating||!loaded" @click="resetMask">重置蒙版</button><button :aria-expanded="precise" @click="precise=!precise">{{ precise?'收起坐标操作':'坐标辅助操作' }}</button></view>
  <view v-if="precise" class="cutout-precise"><text class="cutout-note">不便在图上操作时，输入图像中的百分比坐标。</text><view class="coordinate-row"><view><text>X（0–100%）</text><input aria-label="圈选横坐标百分比" type="digit" v-model="coordX"/></view><view><text>Y（0–100%）</text><input aria-label="圈选纵坐标百分比" type="digit" v-model="coordY"/></view></view><button :disabled="busy||generating||!loaded" @click="coordinatePoint">{{ tool==='polygon'?'添加圈选点':tool==='background'?'去除此处背景':'在此处落笔' }}</button></view>
  <RangeControl v-if="tool==='erase'||tool==='restore'" label="笔刷大小" :model-value="brush" :min="1" :max="15" :display="brush+'%'" @update:model-value="brush=$event"/>
  <view :class="{'cutout-locked':generating||busy}"><RangeControl label="去背景容差" :model-value="recipe.tolerance" :min="0" :max="100" @update:model-value="setting('tolerance',$event)"/><RangeControl label="轻卡通化" :model-value="recipe.cartoon" :min="0" :max="100" :display="recipe.cartoon+'%'" @update:model-value="setting('cartoon',$event)"/><RangeControl label="轮廓白边" :model-value="recipe.outline" :min="1" :max="10" :display="recipe.outline+'%'" @update:model-value="setting('outline',$event)"/></view>
  <text class="cutout-status" role="status">{{ status }}</text>
  <text v-if="error" class="cutout-error" role="alert">{{ error }}</text><button v-if="fatal" class="cutout-retry" @click="initialize">重新初始化处理器</button>
  <button class="cutout-generate" :disabled="busy||generating||!loaded||waiting||coverage<.0001||coverage>.985||tool==='polygon'" @click="generate">{{ generating?'正在本地生成…':'生成异形冰箱贴' }}</button>
  <view class="cutout-result-title">2 · 冰箱贴效果 <text v-if="dirty">（待重新生成）</text></view>
  <view class="cutout-result"><image v-if="resultUrl||processedUrl" :src="resultUrl||processedUrl" mode="aspectFit" aria-label="透明背景异形冰箱贴预览"/><text v-else>完成抠图后生成预览<br/>透明外形 · 轮廓白边 · 轻卡通化</text></view>
  <text class="cutout-note">{{ dirty?'调整后需重新生成，确认效果再加入手账。':'已生成透明 PNG，可加入手账。' }} 这是本地图像风格化，不是 AI 水彩重绘。</text>
 </view>
</template>
<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import type {Photo} from '../types'
import {defaultRecipe,type Point,type CutoutRecipe,type BrushStroke,type Pixels} from '../core/sticker'
import RangeControl from './RangeControl.vue'
const props=defineProps<{source:Photo;initial?:CutoutRecipe;processedUrl?:string;busy:boolean}>()
const emit=defineEmits<{(e:'dirty'):void;(e:'processing',active:boolean):void;(e:'processed',data:{png:string;recipe:CutoutRecipe}):void}>()
const clone=<T,>(x:T):T=>JSON.parse(JSON.stringify(x))
const recipe=ref<CutoutRecipe>(props.initial?clone(props.initial):defaultRecipe()),tool=ref<'background'|'polygon'|'erase'|'restore'>('background'),polygon=ref<Point[]>([]),history=ref<CutoutRecipe[]>([])
const loaded=ref(false),waiting=ref(false),generating=ref(false),showOriginal=ref(false),fatal=ref(false),error=ref(''),coverage=ref(1),dirty=ref(!props.processedUrl),resultUrl=ref(''),precise=ref(false),coordX=ref('50'),coordY=ref('50'),brush=ref(5)
const status=ref('正在准备本地工作画布…'),canvasId='cutout-'+Math.random().toString(36).slice(2)
let canvas:HTMLCanvasElement,ctx:CanvasRenderingContext2D,source:Pixels,mask:Uint8ClampedArray|undefined,worker:Worker|undefined,sequence=0,requestTimer:ReturnType<typeof setTimeout>|undefined,timeout:ReturnType<typeof setTimeout>|undefined,alive=true,stroke:BrushStroke|undefined
function markDirty(){dirty.value=true;resultUrl.value='';emit('dirty')}
function remember(){history.value.push(clone(recipe.value));if(history.value.length>15)history.value.shift()}
function changed(){markDirty();showOriginal.value=false;requestMask()}
function setting(key:'tolerance'|'cartoon'|'outline',value:number){if(generating.value||props.busy)return;remember();recipe.value[key]=value;changed()}
function resetMask(){remember();recipe.value={...recipe.value,mode:'original',polygon:[],background:[],strokes:[]};polygon.value=[];tool.value='background';changed()}
function autoMask(){remember();recipe.value={...recipe.value,mode:'auto',polygon:[],background:[],strokes:[]};polygon.value=[];tool.value='background';changed()}
function startPolygon(){tool.value='polygon';polygon.value=[];paint()}
function finishPolygon(){if(polygon.value.length<3)return;remember();recipe.value={...recipe.value,mode:'polygon',polygon:clone(polygon.value),background:[],strokes:[]};polygon.value=[];tool.value='background';changed()}
function undo(){if(!history.value.length)return;recipe.value=history.value.pop()!;polygon.value=[];tool.value='background';changed()}
function appendPoint(p:Point){if(polygon.value.length>=128){error.value='最多 128 个圈选点，请完成圈选或撤回后重试';return}polygon.value.push(p);paint()}
function backgroundPoint(p:Point){if(recipe.value.background.length>=32){error.value='背景点已达 32 个，请改用擦除笔刷或重置蒙版';return}remember();recipe.value.background.push(p);changed()}
function finishStroke(){if(!stroke)return;const total=recipe.value.strokes.reduce((n,s)=>n+s.points.length,0);if(recipe.value.strokes.length>=100||total+stroke.points.length>16000){stroke=undefined;error.value='修边操作较多，请撤销部分笔画或重新圈选';paint();return}remember();recipe.value.strokes.push(stroke);stroke=undefined;changed()}
function coordinatePoint(){const x=Number(coordX.value),y=Number(coordY.value);if(coordX.value.trim()===''||coordY.value.trim()===''||!Number.isFinite(x)||!Number.isFinite(y)||x<0||x>100||y<0||y>100){error.value='请输入 0 到 100 的坐标';return}const p={x:x/100,y:y/100};if(tool.value==='polygon')appendPoint(p);else if(tool.value==='background')backgroundPoint(p);else{stroke={mode:tool.value,radius:brush.value/100,points:[p]};finishStroke()}}
function position(e:PointerEvent):Point{const b=canvas.getBoundingClientRect();return {x:Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),y:Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))}}
function down(e:PointerEvent){if(!loaded.value||generating.value||props.busy||!e.isPrimary||e.button!==0)return;e.preventDefault();const p=position(e);if(tool.value==='polygon'){appendPoint(p);return}if(tool.value==='background'){backgroundPoint(p);return}stroke={mode:tool.value,radius:brush.value/100,points:[p]};canvas.setPointerCapture(e.pointerId);paint()}
function move(e:PointerEvent){if(!e.isPrimary||!stroke)return;e.preventDefault();const p=position(e),last=stroke.points.at(-1)!;if(Math.hypot(p.x-last.x,p.y-last.y)<.003)return;if(stroke.points.length<2048)stroke.points.push(p);paint()}
function up(e:PointerEvent){if(!stroke)return;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);finishStroke()}
function paint(){if(!source||!ctx)return;const data=source.data.slice();if(mask&&!showOriginal.value)for(let i=0;i<mask.length;i++)data[i*4+3]=Math.max(Math.round(source.data[i*4+3]*.18),mask[i]);ctx.putImageData(new ImageData(data,source.width,source.height),0,0)
 const points=polygon.value;if(points.length){ctx.save();ctx.lineWidth=Math.max(2,source.width/180);ctx.strokeStyle='#fff';ctx.fillStyle='#365d48';ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x*canvas.width,p.y*canvas.height):ctx.moveTo(p.x*canvas.width,p.y*canvas.height));ctx.stroke();for(const p of points){ctx.beginPath();ctx.arc(p.x*canvas.width,p.y*canvas.height,Math.max(3,source.width/100),0,Math.PI*2);ctx.fill();ctx.stroke()}ctx.restore()}
 if(stroke){ctx.save();ctx.strokeStyle=stroke.mode==='erase'?'#a54148aa':'#276747aa';ctx.lineWidth=stroke.radius*Math.min(source.width,source.height)*2;ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();stroke.points.forEach((p,i)=>i?ctx.lineTo(p.x*canvas.width,p.y*canvas.height):ctx.moveTo(p.x*canvas.width,p.y*canvas.height));if(stroke.points.length===1){const p=stroke.points[0];ctx.lineTo(p.x*canvas.width+.01,p.y*canvas.height)}ctx.stroke();ctx.restore()}}
function failure(message:string){error.value=message;fatal.value=true;loaded.value=false;waiting.value=false;generating.value=false;emit('processing',false);clearTimeout(timeout);worker?.terminate();worker=undefined;status.value='本地处理暂停；原图和已加入的冰箱贴仍保留。'}
function post(type:'mask'|'generate'){if(!worker||!loaded.value)return;const id=++sequence;waiting.value=true;clearTimeout(timeout);timeout=setTimeout(()=>failure('处理超时，可重新初始化后减少笔画或换较小的图片'),15000);worker.postMessage({type,id,recipe:clone(recipe.value)})}
function requestMask(){clearTimeout(requestTimer);waiting.value=true;requestTimer=setTimeout(()=>post('mask'),140);paint()}
function generate(){error.value='';generating.value=true;emit('processing',true);clearTimeout(requestTimer);post('generate')}
function initialize(){
 clearTimeout(timeout);clearTimeout(requestTimer);worker?.terminate();loaded.value=false;fatal.value=false;error.value='';generating.value=false;emit('processing',false);mask=undefined
 try{
  const host=document.getElementById(canvasId);if(!host)throw new Error('编辑容器尚未准备好');if(!canvas){canvas=document.createElement('canvas');canvas.setAttribute('aria-label','主体轮廓编辑画布，可点击圈选或使用下方坐标辅助操作');canvas.style.cssText='display:block;width:auto;max-width:100%;height:auto;max-height:360px;margin:auto;touch-action:none';host.appendChild(canvas);canvas.addEventListener('pointerdown',down);canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerup',up);canvas.addEventListener('pointercancel',up)}
  const scale=Math.min(1,768/Math.max(props.source.width,props.source.height));canvas.width=Math.max(1,Math.round(props.source.width*scale));canvas.height=Math.max(1,Math.round(props.source.height*scale));const c=canvas.getContext('2d',{willReadFrequently:true});if(!c)throw new Error('浏览器无法准备本地 Canvas');ctx=c;ctx.clearRect(0,0,canvas.width,canvas.height);ctx.drawImage(props.source.source as CanvasImageSource,0,0,canvas.width,canvas.height);const raw=ctx.getImageData(0,0,canvas.width,canvas.height);source={data:raw.data,width:raw.width,height:raw.height};paint()
  worker=new Worker(new URL('../platform/sticker-worker.ts',import.meta.url),{type:'module'});worker.onerror=()=>failure('本地处理线程加载失败，请刷新页面或重新初始化');worker.onmessage=event=>{if(!alive)return;const msg=event.data;if(msg.type==='ready'){clearTimeout(timeout);loaded.value=true;status.value='已准备好，本地试去背景中…';requestMask();return}if(msg.id!==sequence)return;clearTimeout(timeout);waiting.value=false;if(msg.type==='error'){error.value=msg.message;generating.value=false;emit('processing',false);return}coverage.value=msg.bounds.coverage;status.value=coverage.value>.985?'背景尚未分离：请圈选主体或擦除背景。':coverage.value<.0001?'主体被清空了：请补回或重新圈选。':`当前保留约 ${Math.round(coverage.value*100)}% 像素；请检查主体是否完整。`
   if(msg.type==='mask'){mask=msg.mask;paint();return}
   if(msg.type==='generate'){try{const p=msg.result as Pixels,c=document.createElement('canvas');c.width=p.width;c.height=p.height;const x=c.getContext('2d');if(!x)throw new Error('透明图片生成失败');x.putImageData(new ImageData(p.data,p.width,p.height),0,0);const output=document.createElement('canvas');output.width=p.width;output.height=p.height;const ox=output.getContext('2d')!;ox.shadowColor='#50423150';ox.shadowBlur=3;ox.shadowOffsetY=2;ox.drawImage(c,0,0);const png=output.toDataURL('image/png');c.width=c.height=1;output.width=output.height=1;resultUrl.value=png;dirty.value=false;emit('processed',{png,recipe:clone(recipe.value)})}catch(e){error.value=e instanceof Error?e.message:'生成失败'}finally{generating.value=false;emit('processing',false)}}
  };const copy=source.data.slice();worker.postMessage({type:'init',id:0,source:{...source,data:copy}},[copy.buffer]);timeout=setTimeout(()=>failure('本地处理器未响应，请重试'),15000)
 }catch(e){failure(e instanceof Error?e.message:'本地处理初始化失败')}
}
onMounted(initialize)
onBeforeUnmount(()=>{alive=false;clearTimeout(timeout);clearTimeout(requestTimer);worker?.terminate();if(canvas){canvas.removeEventListener('pointerdown',down);canvas.removeEventListener('pointermove',move);canvas.removeEventListener('pointerup',up);canvas.removeEventListener('pointercancel',up);canvas.remove();canvas.width=canvas.height=1}emit('processing',false)})
</script>
<style scoped>
.cutout-note,.cutout-instruction,.cutout-status{display:block;font-size:14px;line-height:1.65;color:#596552;margin:10px 0}.cutout-tools{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:12px 0}.local-cutout button{font-size:14px;min-height:44px;line-height:22px;padding:10px 4px;border:1px solid #cdd5c5;background:#fffdf7;color:#405b47;min-width:0}.local-cutout button.active{border:2px solid #617858;padding:9px 3px;background:#e7eddc}.cutout-canvas-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:14px;margin:16px 0 8px}.cutout-canvas-heading button{font-size:14px;padding:10px 8px}.cutout-editor,.cutout-result{background-color:#fff;background-image:linear-gradient(45deg,#e3e6dc 25%,transparent 25%),linear-gradient(-45deg,#e3e6dc 25%,transparent 25%),linear-gradient(45deg,transparent 75%,#e3e6dc 75%),linear-gradient(-45deg,transparent 75%,#e3e6dc 75%);background-size:16px 16px;background-position:0 0,0 8px,8px -8px,-8px 0;border:1px solid #bfc9b6;border-radius:6px;overflow:hidden}.cutout-result{margin:12px 0;min-height:160px;display:flex;align-items:center;justify-content:center;padding:12px}.cutout-result image{width:100%;height:180px}.cutout-result text{font-size:14px;text-align:center;line-height:1.8;color:#52634c}.cutout-result-title{font-size:15px;font-weight:600;margin-top:20px}.cutout-result-title text{font-size:14px;font-weight:400;color:#785c38}.cutout-error{display:block;margin:12px 0;color:#8c3c2d;background:#fff0e6;font-size:14px;line-height:1.6;padding:10px;border:1px solid #dca68e}.local-cutout .cutout-generate{width:100%;background:#3f5a45;color:#fffdf7;border-color:#3f5a45;margin-top:12px;min-height:48px}.cutout-precise{padding:12px;background:#fffdf5;border:1px solid #dce1d2;border-radius:6px}.coordinate-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0}.coordinate-row text{font-size:14px}.coordinate-row input{height:44px;background:#f5f5ed;border:1px solid #ccd4c2;border-radius:4px;padding:8px;font-size:16px;width:100%;box-sizing:border-box}.cutout-locked{pointer-events:none;opacity:.6}button[disabled]{opacity:.5}button:focus-visible{outline:3px solid #617858;outline-offset:2px}.polygon-actions>text{font-size:14px;color:#52634c}
</style>
